// Tests for `deploymentBundle()` in ../gpu-setup-model.js — the `modal_app.py` generator.
//
// The suite asserts on structure and on the exact flags that end up in the generated file. It does
// NOT run Python: the generated file's syntactic validity is checked outside the suite (the module
// was verified with `python3 -c "import ast; ast.parse(...)"` while it was written), because a test
// that shells out to an interpreter is a test that fails on a machine without one — and this panel
// has no build step and no runtime dependencies.
//
// Provenance for the rules asserted here: docs/research/ARCHITECTURE-gpu-rentals.md §2.1, §7, §11;
// docs/research/modal-platform.md (canonical GPU ids, scaledown_window bounds, no deployment REST
// API, `modal deploy` options); docs/research/requantize-recipes.md §6.4 (never synthesise
// `--quantization`).

import test from 'node:test';
import assert from 'node:assert/strict';

import { deploymentBundle, applySizing } from '../gpu-setup-model.js';

const GiB = 1024 ** 3;

const ARCH = {
  num_hidden_layers: 64,
  layer_types: [...Array(48).fill('linear_attention'), ...Array(16).fill('full_attention')],
  num_attention_heads: 24,
  num_key_value_heads: 4,
  head_dim: 256,
  hidden_size: 5120,
  max_position_embeddings: 262144,
  torch_dtype: 'bfloat16',
};

function makeCatalog(gpus) {
  return {
    platforms: [{ id: 'modal', label: 'Modal', gpus }],
    quant_methods: [
      { id: 'fp8', label: 'FP8', bytes_per_param: 1, min_compute_cap: 8.9 },
      { id: 'bf16', label: 'BF16', bytes_per_param: 2, min_compute_cap: 8 },
      { id: 'awq', label: 'AWQ 4-bit', bytes_per_param: 0.5, min_compute_cap: 7.5, produced_quant_method: 'compressed-tensors' },
      { id: 'none', label: 'None', bytes_per_param: 2, min_compute_cap: 8 },
    ],
    kv_cache_dtypes: [
      { id: 'auto' },
      { id: 'fp8', bytes_per_element: 1, min_compute_cap: 8.9 },
    ],
  };
}

const CATALOG = makeCatalog([
  { id: 'RTX-PRO-6000', vram_gib: 96, usable_vram_gib: 95, compute_capability: '12.0', price_usd_per_second: 0.000842, free_plan: 'unavailable' },
  { id: 'L40S', vram_gib: 48, usable_vram_gib: 46, compute_capability: '8.9', price_usd_per_second: 0.000542, free_plan: 'available' },
  { id: 'A10', vram_gib: 24, compute_capability: 8.6, price_usd_per_second: 0.000306, free_plan: 'unknown' },
  { id: 'H100', vram_gib: 80, compute_capability: 9.0, price_usd_per_second: 0.001097, free_plan: 'unavailable' },
  { id: 'B300', vram_gib: 288, compute_capability: '10.3', price_usd_per_second: 0.001972, free_plan: 'unavailable' },
  { id: 'A10G', vram_gib: 24, compute_capability: 8.6, price_usd_per_second: 0.000306, free_plan: 'unknown' },
]);

const PUBLIC_PROBE = {
  repo: 'Qwen/Qwen3.8-27B',
  revision: 'main',
  gated: { state: false },
  arch: ARCH,
  dtype: 'bfloat16',
  params: { total: 27781427952, source: 'huggingface safetensors' },
  quants: [{ id: 'fp8', in_repo: true }],
};

const GATED_PROBE = {
  ...PUBLIC_PROBE,
  repo: 'orcarouter/Qwen3.8-27B-Uncensored-FP8',
  revision: 'b32584cc',
  gated: { state: 'manual' },
};

function draft(overrides = {}) {
  return {
    platform: 'modal',
    accountId: 'mana-modal',
    plan: 'paid',
    tokenId: 'wk-example',
    tokenSecret: 'ws-example',
    hfToken: '',
    hfTokenNeeded: false,
    repo: PUBLIC_PROBE.repo,
    revision: '',
    gpu: 'RTX-PRO-6000',
    gpuCount: 1,
    weightQuant: 'fp8',
    kvCacheDtype: 'fp8',
    maxModelLen: 262144,
    maxNumSeqs: 54,
    shutdownCooldownSecs: 60,
    mode: 'interactive',
    batchGpu: null,
    gpuMemoryUtilization: 0.92,
    baseUrl: 'https://mana--qwen-3-8-27b.modal.run',
    sizing: null,
    probe: PUBLIC_PROBE,
    ...overrides,
  };
}

/** The canonical case: one generation through the real sizing path, so the text is what ships. */
function canonical(overrides = {}, probe = PUBLIC_PROBE, catalog = CATALOG) {
  const d = draft({ probe, ...overrides });
  return { draft: d, sizing: applySizing(d, probe, catalog).sizing, bundle: deploymentBundle(d, applySizing(d, probe, catalog).sizing, catalog) };
}

test('deploymentBundle returns the frozen surface: filename, text, command, notes', () => {
  const { bundle } = canonical();
  assert.deepEqual(Object.keys(bundle).sort(), ['command', 'filename', 'notes', 'text', 'warnings']);
  assert.equal(bundle.filename, 'modal_app.py');
  assert.equal(bundle.command, 'modal deploy modal_app.py');
  assert.equal(typeof bundle.text, 'string');
  assert.ok(Array.isArray(bundle.notes));
  assert.ok(Array.isArray(bundle.warnings));
  assert.ok(bundle.notes.length > 0);
});

test('the generated file is a runnable Modal app that serves the OpenAI API from vLLM', () => {
  const { bundle } = canonical();
  const text = bundle.text;

  assert.match(text, /^"""modal_app\.py — generated by Manarouter's GPU setup flow\./);
  assert.match(text, /^import modal$/m);
  assert.match(text, /app = modal\.App\("qwen3-8-27b-rtx-pro-6000"\)/);
  assert.match(text, /modal\.Image\.debian_slim\(python_version="3\.12"\)/);
  assert.match(text, /\.pip_install\("vllm==0\.24\.0"\)/);
  assert.match(text, /modal\.Volume\.from_name\("manarouter-hf-cache", create_if_missing=True\)/);
  assert.match(text, /volumes=\{"\/root\/\.cache\/huggingface": hf_cache\}/);
  assert.match(text, /@app\.function\(/);
  assert.match(text, /gpu="RTX-PRO-6000",/);
  assert.match(text, /scaledown_window=60,/);
  assert.match(text, /startup_timeout=900,/);
  assert.match(text, /@modal\.web_server\(port=8000, requires_proxy_auth=True\)/);
  assert.match(text, /subprocess\.Popen\(\["vllm", "serve", \*VLLM_ARGS\]\)/);
  assert.equal((text.match(/"""/g) ?? []).length, 2, 'the module docstring is the only triple-quoted string');
  assert.ok(text.endsWith('process.wait()\n'));
});

test('vLLM flags come from the draft and never invent a value', () => {
  const { bundle } = canonical({ maxNumSeqs: 54, revision: 'b32584cc' });
  const text = bundle.text;

  assert.match(text, /"--model", "Qwen\/Qwen3\.8-27B",/);
  assert.match(text, /"--revision", "b32584cc",/);
  assert.match(text, /"--kv-cache-dtype", "fp8",/);
  assert.match(text, /"--max-model-len", "262144",/);
  assert.match(text, /"--max-num-seqs", "54",/);
  assert.match(text, /"--gpu-memory-utilization", "0\.92",/);
  assert.match(text, /"--host", "0\.0\.0\.0",\n\s+"--port", "8000",/);
});

test('--revision is emitted only when the draft pins one', () => {
  assert.doesNotMatch(canonical({ revision: '' }).bundle.text, /--revision/);
  assert.match(canonical({ revision: 'b32584cc' }).bundle.text, /"--revision", "b32584cc",/);
});

test('--max-model-len and --max-num-seqs are omitted while they are unset', () => {
  const { bundle } = canonical({ maxModelLen: null, maxNumSeqs: null });
  assert.doesNotMatch(bundle.text, /--max-model-len/);
  assert.doesNotMatch(bundle.text, /--max-num-seqs/);
  assert.doesNotMatch(bundle.text, /--gpu-memory-utilization", "null/);
});

// ---------------------------------------------------------------------------
// C1b regression guard: no --quantization flag, for any quant, ever.
// ---------------------------------------------------------------------------

test('no --quantization flag is emitted for any selected quant (C1b regression guard)', () => {
  // The loop is the guard: a future quant cannot slip a flag back in. A flag that disagrees with
  // the checkpoint's own quant_method makes vLLM raise ValueError at startup — a paid container
  // that serves nothing. Auto-detection is authoritative for both AutoAWQ and compressed-tensors
  // artefacts (docs/research/requantize-recipes.md §6.4).
  for (const weightQuant of ['none', 'bf16', 'fp8', 'awq', 'gptq', 'compressed-tensors']) {
    const { bundle } = canonical({ weightQuant });
    assert.doesNotMatch(bundle.text, /--quantization/, `weightQuant="${weightQuant}" must not emit --quantization`);
  }
});

test('the archetypal compressed-tensors trap: awq selected, awq-produces-compressed-tensors entry', () => {
  // Exactly the orchestrator's C1b repro: the catalog says this "awq" entry is produced as
  // quant_method "compressed-tensors", so the flag is the one thing that must not be there.
  const { bundle } = canonical({ weightQuant: 'awq' });
  assert.doesNotMatch(bundle.text, /--quantization/);
  assert.match(bundle.text, /"--kv-cache-dtype", "fp8",/);
  assert.ok(bundle.warnings.some((w) => w.includes('compressed-tensors') && w.includes('ValueError')),
    'the produced-vs-requested disagreement is surfaced as a warning');
});

test('a quant the repo does not ship produces a note naming the requantisation recipe', () => {
  const { bundle } = canonical({ weightQuant: 'bf16' }); // the probe ships fp8 only
  assert.doesNotMatch(bundle.text, /--quantization/);
  const note = bundle.notes.find((n) => n.includes('not what this repo ships'));
  assert.ok(note, 'a note says the quant is not in the checkout');
  assert.match(note, /requantisation recipe/);
  assert.match(note, /point --model at the output directory/);
  assert.match(note, /it ships fp8/);
  assert.ok(bundle.warnings.some((w) => w.includes('does not ship "bf16"')), 'and a warning says the bundle cannot serve it');
});

test('a quant the repo does ship says vLLM detects it from the checkpoint', () => {
  const { bundle } = canonical({ weightQuant: 'fp8' });
  const note = bundle.notes.find((n) => n.includes('vLLM detects fp8'));
  assert.ok(note, 'the note explains why no flag is needed');
  assert.match(note, /ValueError/);
  assert.match(note, /container serves nothing/);
});

test('with no probe-resolved quants the note says so rather than guessing', () => {
  const { bundle } = canonical({ weightQuant: 'fp8', probe: null });
  const note = bundle.notes.find((n) => n.includes('probe has not resolved'));
  assert.ok(note, 'silence about the repo ships is stated as silence');
  assert.doesNotMatch(bundle.text, /--quantization/);
});

test('the "none" quant says the checkpoint serves at its own dtype', () => {
  const { bundle } = canonical({ weightQuant: 'none' });
  assert.ok(bundle.notes.some((n) => n.includes('serves at its own dtype')));
  assert.doesNotMatch(bundle.text, /--quantization/);
});

// ---------------------------------------------------------------------------
// Gating, secrets, and what must never be embedded
// ---------------------------------------------------------------------------

test('a gated repo references the Modal secret by name and embeds no token', () => {
  const { bundle } = canonical({ repo: GATED_PROBE.repo, revision: 'b32584cc', probe: GATED_PROBE, hfTokenNeeded: true }, GATED_PROBE);
  assert.match(bundle.text, /secrets=\[modal\.Secret\.from_name\("manarouter-hf"\)\],/);
  assert.ok(bundle.notes.some((n) => n.includes('modal secret create manarouter-hf HF_TOKEN=...')));
  assert.match(bundle.notes.find((n) => n.includes('modal secret create')) ?? '', /never touches this panel/);
});

test('a public repo attaches no secret', () => {
  const { bundle } = canonical();
  assert.doesNotMatch(bundle.text, /Secret\.from_name/);
  assert.doesNotMatch(bundle.text, /secrets=/);
  assert.ok(bundle.notes.some((n) => n.includes('no HuggingFace secret is attached')));
});

test('no credential, no modal.Secret literal, and no credential-shaped value reaches the file', () => {
  const { bundle } = canonical({ repo: GATED_PROBE.repo, probe: GATED_PROBE, hfTokenNeeded: true, hfToken: 'hf_thisMustNeverAppear', tokenId: 'wk-secret', tokenSecret: 'ws-secret' });
  const text = bundle.text;
  assert.doesNotMatch(text, /hf_thisMustNeverAppear/);
  assert.doesNotMatch(text, /hf_[A-Za-z0-9]{8,}/);
  assert.doesNotMatch(text, /wk-secret|ws-secret/);
  assert.doesNotMatch(text, /modal\.Secret\(/); // only modal.Secret.from_name(...)
  assert.doesNotMatch(text, /HF_TOKEN=/); // the env var is created by `modal secret create`, not by us
});

test('the file never contains the javascript spellings null or undefined', () => {
  for (const overrides of [{}, { maxModelLen: null, maxNumSeqs: null, revision: '', gpu: 'H100' }, { gpuCount: 8, gpu: 'A10' }]) {
    const { bundle } = canonical(overrides);
    assert.doesNotMatch(bundle.text, /\bnull\b/);
    assert.doesNotMatch(bundle.text, /\bundefined\b/);
    assert.doesNotMatch(bundle.text, /NaN/);
  }
});

// ---------------------------------------------------------------------------
// scaledown_window clamping (Modal: default 60, min 2, max 1200)
// ---------------------------------------------------------------------------

test('scaledown_window is clamped to Modal\u2019s 2–1200 s range and says when it clamped', () => {
  const low = canonical({ shutdownCooldownSecs: 1 }).bundle;
  assert.match(low.text, /scaledown_window=2,/);
  assert.ok(low.notes.some((n) => n.includes('5000') === false && n.includes('1 s was outside')));

  const high = canonical({ shutdownCooldownSecs: 5000 }).bundle;
  assert.match(high.text, /scaledown_window=1200,/);
  assert.ok(high.notes.some((n) => n.includes('5000 s was outside') && n.includes('1200 s')));
  assert.doesNotMatch(high.text, /scaledown_window=5000/);
});

test('an unset cooldown gets Modal\u2019s default 60 s with no clamp note', () => {
  const { bundle } = canonical({ shutdownCooldownSecs: null });
  assert.match(bundle.text, /scaledown_window=60,/);
  assert.ok(!bundle.notes.some((n) => n.includes('was outside')));
});

test('an in-range cooldown is used verbatim', () => {
  assert.match(canonical({ shutdownCooldownSecs: 900 }).bundle.text, /scaledown_window=900,/);
});

// ---------------------------------------------------------------------------
// Multi-card, pinning, per-card limits, and the CUDA floor
// ---------------------------------------------------------------------------

test('H100 is pinned as H100! and the pin is explained', () => {
  const { bundle } = canonical({ gpu: 'H100' });
  assert.match(bundle.text, /gpu="H100!",/);
  assert.ok(bundle.notes.some((n) => n.includes('Card pinned') && n.includes('H100!') && n.includes('H200')));
  assert.doesNotMatch(bundle.text, /gpu="H100",/); // the bare id may be served on an H200
});

test('a card without an auto-upgrade is requested by its canonical id', () => {
  assert.match(canonical({ gpu: 'RTX-PRO-6000' }).bundle.text, /gpu="RTX-PRO-6000",/);
  assert.match(canonical({ gpu: 'L40S' }).bundle.text, /gpu="L40S",/);
  assert.match(canonical({ gpu: 'B200' }).bundle.text, /gpu="B200",/);
});

test('several cards are requested as gpu="<id>:N" with tensor parallelism', () => {
  const { bundle } = canonical({ gpu: 'H100', gpuCount: 8 });
  assert.match(bundle.text, /gpu="H100!:8",/);
  assert.match(bundle.text, /"--tensor-parallel-size", "8",/);
  assert.ok(bundle.notes.some((n) => n.includes('Multi-card') && n.includes('--tensor-parallel-size 8')));
});

test('one card carries no tensor-parallel flag', () => {
  assert.doesNotMatch(canonical({ gpu: 'H100', gpuCount: 1 }).bundle.text, /--tensor-parallel-size/);
});

test('A10 is capped at 4 cards per container and the clamp is stated', () => {
  const { bundle } = canonical({ gpu: 'A10', gpuCount: 8 });
  assert.match(bundle.text, /gpu="A10:4",/);
  assert.match(bundle.text, /"--tensor-parallel-size", "4",/);
  const note = bundle.notes.find((n) => n.includes('at most 4 of these cards'));
  assert.ok(note, 'the per-card limit is visible, not silent');
  assert.match(note, /you asked for 8/);
  assert.match(note, /A10 is the published exception at 4/);
});

test('a card with the 8-card default keeps the requested count', () => {
  assert.match(canonical({ gpu: 'RTX-PRO-6000', gpuCount: 8 }).bundle.text, /gpu="RTX-PRO-6000:8",/);
});

test('B300 warns that the card needs CUDA 13.1+ and never pretends a CUDA-12 image works', () => {
  const { bundle } = canonical({ gpu: 'B300', weightQuant: 'none' });
  assert.match(bundle.text, /WARNING: B300 needs CUDA 13\.1\+/);
  assert.match(bundle.text, /a CUDA-12 image cannot drive this card/);
  assert.ok(bundle.notes.some((n) => n.includes('B300 needs CUDA 13.1+') && n.includes('fails at startup')));
  // and no CUDA base image is pinned silently: the file's only image is debian_slim + pip_install
  assert.doesNotMatch(bundle.text, /cuda12[0-9]/i);
  assert.doesNotMatch(bundle.text, /nvidia\/cuda/i);
});

test('an A10G card keeps the operator\u2019s value but is named as non-canonical', () => {
  const { bundle } = canonical({ gpu: 'A10G' });
  assert.match(bundle.text, /gpu="A10G",/);
  assert.ok(bundle.notes.some((n) => n.includes('is not a current Modal GPU id') && n.includes('"A10"')));
});

test('a GPU the catalog does not carry is flagged rather than silently sized', () => {
  const { bundle } = canonical({ gpu: 'V100' });
  assert.match(bundle.text, /gpu="V100",/);
  assert.ok(bundle.notes.some((n) => n.includes('"V100" is not in the catalog')));
});

// ---------------------------------------------------------------------------
// The honest caveats the whole design rests on
// ---------------------------------------------------------------------------

test('the notes say the bundle is the deployment because Modal has no deployment API', () => {
  const { bundle } = canonical();
  assert.ok(bundle.notes.some((n) => n.includes('no deployment REST API') && n.includes('modal deploy modal_app.py')));
});

test('the notes say vLLM\u2019s own startup line overrides Manarouter\u2019s KV estimate', () => {
  const { bundle } = canonical();
  const note = bundle.notes.find((n) => n.includes('GPU KV cache size: N tokens'));
  assert.ok(note, 'the authoritative number is named');
  assert.match(note, /1784103 tokens/);
  assert.match(note, /analytic estimate/);
  assert.ok(!bundle.notes.some((n) => n.includes('validated')), 'the estimate is never called validated');
});

test('the notes carry the deploy CLI surface and never a --detach flag', () => {
  const { bundle } = canonical();
  const note = bundle.notes.find((n) => n.includes('--strategy [rolling|recreate]'));
  assert.ok(note, 'the real modal deploy options are named');
  assert.match(note, /There is no --detach/);
  assert.doesNotMatch(bundle.text, /--detach/);
  assert.doesNotMatch(bundle.command, /--detach/);
  assert.doesNotMatch(bundle.text, /--strategy/); // options belong to the command the operator runs, not to app.py
});

test('the notes refuse to turn per-second billing into an hourly figure', () => {
  const { bundle } = canonical();
  assert.ok(bundle.notes.some((n) => n.includes('bills per second') && n.includes('an hour-based figure is not the same number')));
  assert.ok(!bundle.notes.some((n) => n.includes('730')), 'no always-on monthly arithmetic sneaks in');
});

test('a baseUrl in the draft is echoed back so the operator can compare it with the real URL', () => {
  const { bundle } = canonical({ baseUrl: 'https://mana--x.modal.run' });
  assert.ok(bundle.notes.some((n) => n.includes('https://mana--x.modal.run') && n.includes('modal deploy` prints for this app')));
});

test('an unavailable sizing says the provider will need vLLM\u2019s own number', () => {
  const { bundle } = canonical({ kvCacheDtype: 'auto' },
    { ...PUBLIC_PROBE, dtype: undefined, arch: { ...ARCH, torch_dtype: undefined } });
  assert.match(bundle.text, /Sizing:\s+not estimated/);
  assert.ok(bundle.notes.some((n) => n.includes('No KV estimate was available')));
});

test('the generated file is stable: same draft, same text', () => {
  const a = canonical().bundle;
  const b = canonical().bundle;
  assert.equal(a.text, b.text);
  assert.deepEqual(a.notes, b.notes);
});

test('the module docstring records the model, the card and that the size is an estimate', () => {
  const { bundle } = canonical({ revision: 'b32584cc' });
  assert.match(bundle.text, /^Model:\s+Qwen\/Qwen3\.8-27B @ b32584cc$/m);
  assert.match(bundle.text, /^Card:\s+RTX-PRO-6000/m);
  assert.match(bundle.text, /^Sizing:\s+Manarouter estimate 1784103 KV tokens — an estimate, not vLLM's measurement$/m);
  assert.match(bundle.text, /^Run it with:\s+modal deploy modal_app\.py$/m);
});
